queries.sparql:
PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX eli: <http://data.europa.eu/eli/ontology#>
PREFIX eli-dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?committee ?label ?term ?start ?end ?termStart ?termEnd ?range ?period ?termType WHERE {
  GRAPH <https://data.oireachtas.ie/graph/committees> {
    ?committee a members:Committee .
    OPTIONAL { ?committee members:committeeInHouseTerm ?term . }
    OPTIONAL { ?committee skos:prefLabel ?label . }
    OPTIONAL { ?committee members:hasCommitteeDateRange ?range . ?range a members:DateRange . OPTIONAL { ?range members:StartDate ?start . } OPTIONAL { ?range members:EndDate ?end . } }
  }
  OPTIONAL { GRAPH <https://data.oireachtas.ie/graph/houses> { ?term a ?termType . VALUES ?termType { agents:DailTerm agents:SeanadTerm } ?term dct:temporal ?period . ?period a dct:PeriodOfTime . OPTIONAL { ?period dcat:startDate ?termStart . } OPTIONAL { ?period dcat:endDate ?termEnd . } } }
} ORDER BY ?committee ?label ?term ?start ?end ?termStart ?termEnd ?range ?period ?termType
LIMIT 100

